import{_ as t,o as i,c as o,a5 as a}from"./chunks/framework.BEZBAInb.js";const p=JSON.parse('{"title":"Code Contributions","description":"","frontmatter":{"title":"Code Contributions","order":3},"headers":[],"relativePath":"en/2.4/community/code-contribute.md","filePath":"en/2.4/community/code-contribute.md","lastUpdated":1788455378000}'),s={name:"en/2.4/community/code-contribute.md"};function n(r,e,l,d,c,h){return i(),o("div",null,[...e[0]||(e[0]=[a(`<h1 id="code-contribution-guide" tabindex="-1">Code Contribution Guide <a class="header-anchor" href="#code-contribution-guide" aria-label="Permalink to &quot;Code Contribution Guide&quot;">​</a></h1><h2 id="ways-to-contribute" tabindex="-1">Ways to Contribute <a class="header-anchor" href="#ways-to-contribute" aria-label="Permalink to &quot;Ways to Contribute&quot;">​</a></h2><p>Documentation, code, and other content can all be contributed in the following ways:</p><ul><li><strong>Pull Request</strong>: Submit code to the repository. It will be merged into the main branch after code review.</li><li><strong>Issue</strong>: Submit problems or suggestions. After discussion, the team decides whether to implement them and assigns them to developers.</li></ul><h2 id="code-contribution-workflow" tabindex="-1">Code Contribution Workflow <a class="header-anchor" href="#code-contribution-workflow" aria-label="Permalink to &quot;Code Contribution Workflow&quot;">​</a></h2><p>Before submitting code, make sure Git global configuration has been completed locally. The commit email and username configured in local Git <strong>must match the email and username registered on the platform</strong>. Otherwise, incorrect commit records may be generated and cannot be counted in the contributor list.</p><p>If you are not sure whether your email and username are correct, check your Git configuration in the terminal:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --global</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user.name</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --global</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user.email</span></span></code></pre></div><p>If you need to modify them, use the following commands. Replace &quot;Your Name&quot; and &quot;<a href="mailto:your.email@example.com" target="_blank" rel="noreferrer">your.email@example.com</a>&quot; with your username and email address:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --global</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user.name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Your Name&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --global</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user.email</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;your.email@example.com&quot;</span></span></code></pre></div><p>After completing the configuration, restarting the terminal is recommended to ensure the settings take effect.</p><ol><li><strong>Fork the project</strong>: Click Fork in the upper-right corner to copy it to your own repository</li><li><strong>Create a branch</strong>: <code>git checkout -b feature/your-feature</code></li><li><strong>Commit changes</strong>: <code>git commit -m &quot;feat: describe your changes&quot;</code></li><li><strong>Push the branch</strong>: <code>git push origin feature/your-feature</code></li><li><strong>Submit a PR</strong>: Create a Pull Request</li></ol><p>Contributed code will go through code review and be merged into the main branch after approval.</p><h2 id="gdscript-style-reference" tabindex="-1">GDScript Style Reference <a class="header-anchor" href="#gdscript-style-reference" aria-label="Permalink to &quot;GDScript Style Reference&quot;">​</a></h2><p>This project follows the code style rules in Godot&#39;s official <a href="https://docs.godotengine.org/en/stable/tutorials/scripting/gdscript/gdscript_styleguide.html" target="_blank" rel="noreferrer">GDScript style guide</a>. The following are reference conventions:</p><h3 id="formatting" tabindex="-1">Formatting <a class="header-anchor" href="#formatting" aria-label="Permalink to &quot;Formatting&quot;">​</a></h3><ul><li><strong>Indentation</strong>: Use tabs instead of spaces, with one tab per indentation level</li><li><strong>Line length</strong>: Keep lines within 100 characters, preferably under 80 characters, otherwise readability may suffer</li><li><strong>Line endings</strong>: Use LF line endings and keep a trailing newline at the end of files to avoid Git conflicts</li><li><strong>Encoding</strong>: Use UTF-8 without BOM to avoid garbled text</li></ul><p>In general, Godot&#39;s default script editor or VSCode can automatically satisfy these formatting requirements. If you use another editor, please pay attention to these rules.</p><h3 id="naming-conventions" tabindex="-1">Naming Conventions <a class="header-anchor" href="#naming-conventions" aria-label="Permalink to &quot;Naming Conventions&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Element type</th><th>Naming style</th><th>Example</th></tr></thead><tbody><tr><td>File name</td><td>snake_case</td><td><code>player_controller.gd</code></td></tr><tr><td>Class name</td><td>PascalCase</td><td><code>class_name PlayerController</code></td></tr><tr><td>Function/variable</td><td>snake_case</td><td><code>func move_player()</code></td></tr><tr><td>Signal</td><td>snake_case (past tense)</td><td><code>signal door_opened</code></td></tr><tr><td>Constant</td><td>CONSTANT_CASE</td><td><code>const MAX_HEALTH = 100</code></td></tr><tr><td>Enum name</td><td>PascalCase</td><td><code>enum GameState</code></td></tr><tr><td>Enum value</td><td>CONSTANT_CASE</td><td><code>IDLE, RUNNING, JUMPING</code></td></tr></tbody></table><p>Only English names are allowed in scripts. Do not use other languages, as this may cause problems.</p><h3 id="commenting-rules" tabindex="-1">Commenting Rules <a class="header-anchor" href="#commenting-rules" aria-label="Permalink to &quot;Commenting Rules&quot;">​</a></h3><ul><li><strong>Class comments</strong>: Each class needs a comment at the top describing its purpose and usage. This comment is automatically generated into the documentation, so please make it as detailed as possible.</li><li><strong>Function comments</strong>: Each public function needs a comment above it describing the function, parameters, and return value. Comments may be omitted for private functions or internal utility functions.</li><li><strong>Variable comments</strong>: Add comments for necessary variables, especially those with specific meanings or uses.</li><li><strong>Signal comments</strong>: Each signal needs a comment above it describing its purpose and parameters.</li><li><strong>TODO comments</strong>: If you need to add a todo item, use a <code>TODO</code> comment and describe the task and its priority.</li></ul><h2 id="commit-rules" tabindex="-1">Commit Rules <a class="header-anchor" href="#commit-rules" aria-label="Permalink to &quot;Commit Rules&quot;">​</a></h2><p>For an open-source project, the initial learning cost and adaptation process for commit messages does require some effort, but the long-term return is significant. A strict message convention can save developers time in understanding and communication, while also making CHANGELOG generation easier and more standardized.</p><h3 id="commit-message" tabindex="-1">Commit Message <a class="header-anchor" href="#commit-message" aria-label="Permalink to &quot;Commit Message&quot;">​</a></h3><p>This project refers to the Conventional Commits 1.0.0 specification. The format is:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;type&gt;(&lt;scope)&gt;: &lt;subject&gt;</span></span></code></pre></div><p>It contains three fields: <code>type</code> (required), <code>scope</code> (optional), and <code>subject</code> (required).</p><p><strong><code>type</code></strong> describes the category of the commit. Use one of the following identifiers:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Type</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>feat</strong></td><td style="text-align:left;">New feature</td></tr><tr><td style="text-align:left;"><strong>fix</strong></td><td style="text-align:left;">Bug fix</td></tr><tr><td style="text-align:left;"><strong>docs</strong></td><td style="text-align:left;">Documentation changes</td></tr><tr><td style="text-align:left;"><strong>test</strong></td><td style="text-align:left;">Add tests or modify existing tests</td></tr><tr><td style="text-align:left;"><strong>ci</strong></td><td style="text-align:left;">Changes to CI configuration files and scripts</td></tr></tbody></table><p><strong><code>scope</code></strong> describes the affected area of the commit, depending on the project. It can be a module, component, file, and so on.</p><ul><li><code>feat(something): ...</code></li><li><code>fix(ui): ...</code></li><li><code>docs(readme): ...</code></li><li>If the affected area is broad, it can be omitted or written as <code>(*)</code>.</li></ul><p><strong><code>subject</code></strong> is a short description of the purpose of the commit.</p><p>Examples:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>feat(xxx): add replay feature</span></span>
<span class="line"><span>fix: fix a crash caused by replay speed being too fast in the replay feature</span></span>
<span class="line"><span>docs(readme): update readme</span></span></code></pre></div><h3 id="pull-request" tabindex="-1">Pull Request <a class="header-anchor" href="#pull-request" aria-label="Permalink to &quot;Pull Request&quot;">​</a></h3><p>A PR (Pull Request) is used to submit your code to the main branch of the main repository. Before submitting a PR, make sure your code meets the following requirements:</p><ol><li>The code is formatted correctly and follows the project&#39;s code style.</li><li>Commit messages are standardized and follow the Git commit message rules.</li><li>The submitted code has been tested and has no known issues.</li></ol><p>If these conditions are generally satisfied, you can start submitting the PR.</p><h3 id="pr-submission-rules" tabindex="-1">PR Submission Rules <a class="header-anchor" href="#pr-submission-rules" aria-label="Permalink to &quot;PR Submission Rules&quot;">​</a></h3><p>PR information needs to include the following:</p><ol><li><strong>Title</strong>: Briefly and clearly describe the PR content. A Git commit message can be used.</li><li><strong>Description</strong>: Describe the PR content in detail, including what the feature does, how it is implemented, and what it affects.</li><li><strong>Issue link</strong>: If the PR fixes one or more issues, add the issue links to the PR information.</li></ol><div class="tip custom-block"><p class="custom-block-title">Additional suggestions</p><ol><li>To save maintainers&#39; time and energy, PR descriptions should be as detailed as possible.</li><li>Except for simple bug fixes or text changes, PRs should include a substantial body that explains the change thoroughly.</li><li>Sometimes commits in a PR need to be modified. Please keep an eye on discussions in the PR comments.</li><li>Not every PR will be merged. We apologize in advance for that.</li></ol></div><h2 id="code-review" tabindex="-1">Code Review <a class="header-anchor" href="#code-review" aria-label="Permalink to &quot;Code Review&quot;">​</a></h2><h3 id="review-process" tabindex="-1">Review Process <a class="header-anchor" href="#review-process" aria-label="Permalink to &quot;Review Process&quot;">​</a></h3><p>After a PR is submitted, project maintainers will review the code. During review, maintainers may suggest improvements, including but not limited to code style, performance optimization, and security improvements. Please read the suggestions carefully and make changes accordingly.</p><h3 id="review-standards" tabindex="-1">Review Standards <a class="header-anchor" href="#review-standards" aria-label="Permalink to &quot;Review Standards&quot;">​</a></h3><p>During code review, project maintainers follow these standards:</p><ol><li><strong>Code style</strong>: Ensure the code style follows the project&#39;s style guide.</li><li><strong>Performance optimization</strong>: If the code has serious performance issues, provide a performance optimization plan.</li><li><strong>Documentation updates</strong>: If code changes affect documentation, update the corresponding documentation.</li></ol><div class="tip custom-block"><p class="custom-block-title">Getting help</p><p>In most cases, project maintainers will help you resolve problems encountered during code review and ensure your code can be merged smoothly into the main branch. If you need help, please follow the discussions in the PR comments.</p></div><h2 id="applying-to-become-a-maintainer" tabindex="-1">Applying to Become a Maintainer <a class="header-anchor" href="#applying-to-become-a-maintainer" aria-label="Permalink to &quot;Applying to Become a Maintainer&quot;">​</a></h2><p>After making a certain number of PR contributions to the project, you will be eligible to apply to become a maintainer. If you want to become a maintainer, please apply by email using the following steps:</p><ol><li><p>Prepare your Git account information, including username and email. This will be used to verify your contribution records and send invitation emails later.</p></li><li><p>Prepare project contribution information, including but not limited to links to PRs that have already been submitted and merged, the number of discussions you participated in, and the number of Issues you reported.</p></li><li><p>Send an email to <code>konado@godothub.com</code> with the subject &quot;Apply to become a Konado maintainer&quot;. The email should include the information above.</p></li><li><p>If you are willing, you may include a personal introduction in the email, such as your interests, skills, and experience participating in open-source projects. This helps us better understand you.</p></li></ol><p>The project maintainer team will reply to your application as soon as possible. After confirming your contribution records, we will send an invitation email to your mailbox. Please follow the instructions in the email to confirm your maintainer identity and set up repository permissions.</p><p>We hope you can become a member of the Konado project and contribute to the open-source community together with us!</p>`,56)])])}const m=t(s,[["render",n]]);export{p as __pageData,m as default};
